   223	function isSemanticallyEqual(
   224	  existing: NonNullable<Awaited<ReturnType<typeof findCurrentEventByOrigin>>>,
   225	  params: InsertEventParams
   226	): boolean {
   227	  return (
   228	    (existing.title ?? null) === (params.title ?? null) &&
   229	    (existing.payload_text ?? null) === (params.content ?? null) &&
   230	    existing.payload_type === (params.payloadType ?? 'text') &&
   231	    stableJson(existing.payload_data ?? {}) === stableJson(params.payloadData ?? {}) &&
   232	    stableJson(existing.payload_template ?? null) === stableJson(params.payloadTemplate ?? null) &&
   233	    stableJson(existing.attachments ?? []) === stableJson(params.attachments ?? []) &&
   234	    (existing.author_name ?? null) === (params.authorName ?? null) &&
   235	    (existing.source_url ?? null) === (params.sourceUrl ?? null) &&
   236	    // Only compare occurred_at when the caller supplied one. Insert defaults a
   237	    // missing occurred_at to now(), so an occurredAt-less re-upsert comparing
   238	    // null against the stamped default would supersede on every re-sync.
   239	    (params.occurredAt == null ||
   240	      normalizedTimestamp(existing.occurred_at ?? null) ===
   241	        normalizedTimestamp(params.occurredAt)) &&
   242	    existing.semantic_type === params.semanticType &&
   243	    (existing.origin_type ?? null) === (params.originType ?? null) &&
   244	    stableJson(existing.metadata ?? {}) === stableJson(params.metadata ?? {}) &&
   245	    Number(existing.score ?? 0) === Number(params.score ?? 0) &&
   246	    // Compare the value a supersede would WRITE: a null parentOriginId copies
   247	    // the predecessor's parent (loadEventLineage), so only a caller-supplied
   248	    // parent can differ. Comparing the raw param would re-supersede a
   249	    // copied-parent head on every parentless re-sync, forever.
   250	    (params.parentOriginId == null ||
   251	      (existing.origin_parent_id ?? null) === params.parentOriginId) &&
   252	    existing.interaction_type === (params.interactionType ?? 'none') &&
   253	    (existing.interaction_status ?? null) === (params.interactionStatus ?? null) &&
   254	    stableJson(existing.interaction_input_schema ?? null) ===
   255	      stableJson(params.interactionInputSchema ?? null) &&
   256	    stableJson(existing.interaction_input ?? null) ===
   257	      stableJson(params.interactionInput ?? null) &&
   258	    stableJson(existing.interaction_output ?? null) ===
   259	      stableJson(params.interactionOutput ?? null) &&
   260	    (existing.interaction_error ?? null) === (params.interactionError ?? null)
   261	  );
   262	}
