   264	async function upsertEmbedding(
   265	  eventId: number,
   266	  embedding: number[] | null | undefined,
   267	  embeddingModel: string | null | undefined,
   268	  sql: DbClient = getDb()
   269	): Promise<void> {
   270	  if (!embedding || embedding.length === 0) return;
   271	  // An unstamped vector is unusable — search scopes vector comparison to the
   272	  // configured model — so skip it and let the embed backfill produce a properly
   273	  // stamped one.
   274	  if (!embeddingModel) return;
   275	  const vectorLiteral = `[${embedding.join(',')}]`;
   276	  // Replace this (event, model)'s chunk set with a single chunk-0 row:
   277	  // delete-then-insert scoped to the model so old/new models can coexist
   278	  // during a zero-downtime swap (PK is event_id + embedding_model + chunk_index).
   279	  await sql`DELETE FROM event_embeddings WHERE event_id = ${eventId} AND embedding_model = ${embeddingModel}`;
   280	  await sql`
   281	    INSERT INTO event_embeddings (event_id, chunk_index, embedding, embedding_model)
   282	    VALUES (${eventId}, 0, ${vectorLiteral}::vector, ${embeddingModel})
   283	  `;
   284	}
