   242	/**
   243	 * Ensure each identifier value is present in `entities.metadata.aliases` — the
   244	 * flat alias array the metric compiler resolves event fields against
   245	 * (`metadata->'aliases'`). entity_identities serves recall/authz; aliases serve
   246	 * metrics; both must carry a contact's identifiers or its per-entity metrics
   247	 * silently drop.
   248	 *
   249	 * Lock before merging so concurrent connector transactions cannot clobber one
   250	 * another's aliases or traits. Passing the entity's full identifier set (not
   251	 * just freshly-inserted ones) also repairs a legacy entity whose
   252	 * `entity_identities` predate aliases-on-create.
   253	 */
   254	async function ensureAliases(
   255	  sql: DbClient,
   256	  params: { orgId: string; entityId: number; identifiers: string[] }
   257	): Promise<void> {
   258	  if (params.identifiers.length === 0) return;
   259	  const rows = await sql<{ metadata: Record<string, unknown> | null }>`
   260	    SELECT metadata
   260	    SELECT metadata
   261	    FROM entities
   262	    WHERE id = ${params.entityId}
   263	      AND organization_id = ${params.orgId}
   264	      AND deleted_at IS NULL
   265	    FOR UPDATE
   266	  `;
   267	  if (rows.length === 0) return;
   268	
   269	  const current = rows[0].metadata ?? {};
   270	  const aliases = Array.isArray(current.aliases)
   271	    ? current.aliases.filter((value): value is string => typeof value === 'string')
   272	    : [];
   273	  if (params.identifiers.every((identifier) => aliases.includes(identifier))) return;
   274	
   275	  await patchEntityRows({
   276	    tx: sql,
   277	    ids: [params.entityId],
   278	    patch: {
   279	      metadata: {
   280	        ...current,
   281	        aliases: [...new Set([...aliases, ...params.identifiers])].sort(),
   282	      },
   283	    },
   284	  });
   285	}
