   431	async function createEntityWithIdentities(
   432	  sql: DbClient,
   433	  params: {
   434	    orgId: string;
   435	    connectorKey: string;
   436	    connectionId?: number | null;
   437	    entityType: string;
   438	    title: string;
   439	    identities: ExtractedLink['identities'];
   440	    traits: Map<string, unknown>;
   441	    creatorUserId: string;
   442	  }
   443	): Promise<{ entityId: number; attached: Array<{ namespace: string; identifier: string }> } | null> {
   444	  const persisted = params.identities.filter((i) => !i.matchOnly);
   445	  if (persisted.length === 0) return null;
   446	
   447	  const name = params.title || persisted[0].identifier;
   448	  const metadata: Record<string, unknown> = {};
   449	  for (const [key, value] of params.traits) metadata[key] = value;
   450	
   451	  // Resolve entity_type slug → entity_types(id). Same schema search path as
   452	  // createEntity: try the entity's own org first, then any visibility='public'
   453	  // catalog. First match wins. See createEntity for the slug-poisoning caveat.
   454	  let typeRow = await sql<{ id: number; backing_sql: string | null }>`
   455	    SELECT et.id, et.backing_sql
   456	    FROM entity_types et
   457	    LEFT JOIN organization o ON o.id = et.organization_id
   458	    WHERE et.slug = ${params.entityType}
   459	      AND et.deleted_at IS NULL
   460	      AND (
   461	        et.organization_…2515 tokens truncated… array index) so the caller can write
   693	 * `events.entity_ids` (a webhook row is read by id, not via a feed-time JOIN).
   694	 * `rules` is keyed by event kind (origin_type). Tenant-scoped on `orgId`;
   695	 * entity_identities are UNIQUE per (org, namespace, identifier), so resolution
   696	 * never crosses organizations.
   697	 */
   698	export async function resolveEventAttributionsForItems(
   699	  params: {
   700	    connectorKey: string;
   701	    connectionId?: number | null;
   702	    orgId: string;
   703	    items: BatchItem[];
   704	    rules: RuleMap;
   705	  },
   706	  // Optional transaction handle — the webhook winner passes its tx so the actor
   707	  // graph writes commit atomically with the event insert. A pool or omitted
   708	  // handle opens a transaction here.
   709	  sql?: DbClient
   710	): Promise<Map<number, number[]>> {
   711	  if (params.items.length === 0) return new Map();
   712	  const db = sql ?? getDb();
   713	  return withEntityWriteTransaction(db, (tx) =>
   714	    resolveLinksByKind(
   715	      {
   716	        connectorKey: params.connectorKey,
   717	        connectionId: params.connectionId,
   718	        orgId: params.orgId,
   719	        items: params.items,
   720	        rulesByKind: params.rules,
   721	      },
   722	      tx
   723	    )
   724	  );
   725	}
