   727	/**
   728	 * Core resolver shared by the poll path ({@link applyEventAttributions}) and the
   729	 * webhook path ({@link resolveEventAttributionsForItems}). Given rules grouped by
   730	 * event kind, resolve or auto-create the target entity for each item, stamp the
   731	 * canonical identifier metadata slots (for read-time JOINs), and merge declared
   732	 * traits. Returns a per-item map (by array index) of resolved entity ids.
   733	 */
   734	async function resolveLinksByKind(
   735	  params: {
   736	    connectorKey: string;
   737	    connectionId?: number | null;
   738	    orgId: string;
   739	    items: BatchItem[];
   740	    rulesByKind: RuleMap;
   741	  },
   742	  // A real transaction handle for ALL match/insert/update writes. Public entry
   743	  // points either join the caller's tx or open one before reaching this core.
   744	  sql: DbClient
   745	): Promise<Map<number, number[]>> {
   746	  const resolvedByItem = new Map<number, number[]>();
   747	  if (Object.keys(params.rulesByKind).length === 0 || params.items.length === 0) {
   748	    return resolvedByItem;
   749	  }
   750	
   751	  // entities.created_by is NOT NULL; resolve an org owner/admin once per batch
   752	  // so auto-created entities attribute to a real member rather than a seed user.
   753	  const creatorUserId = await resolveOrgCreator(params.orgId);
   754	
   755	  // rule -> per-item extracted link, carrying the source item + index (the
   756	  // caller recovers the resolved entity per item; metadata is stamped onto the
   757	  // item post-resolution).
   758	  const byRule = new Map<
   759	    ResolvedEventAttributionRule,
   760	    Array<{ index: number; item: BatchItem; link: ExtractedLink }>
   761	  >();
   762	  params.items.forEach((item, index) => {
   763	    const kind = item.origin_type;
   764	    if (!kind) return;
   765	    const rules = params.rulesByKind[kind];
   766	    if (!rules) return;
   767	    for (const rule of rules) {
   768	      const link = extractLink(item, rule);
   769	      if (!link) continue;
   770	      // Metadata stamping is deferred to post-resolution (below) — only
   771	      // attached identifiers are stamped, so a stale one (e.g. a vacated
   772	      // github_login) can't make read-time JOINs attribute to the wrong person.
   773	      let bucket = byRule.get(rule);
   774	      if (!bucket) {
   775	        bucket = [];
   776	        byRule.set(rule, bucket);
   777	      }
   778	      bucket.push({ index, item, link });
   779	    }
   780	  });
   781	  if (byRule.size === 0) return resolvedByItem;
   782	
   783	  // Resolve first, then lock every existing entity in one ascending-id pass.
   784	  // Without a global lock order, two connector batches containing the same
   785	  // entities in opposite item order could deadlock after each locked its first
   786	  // row. Rows that disappeared between lookup and lock are removed from the
   787	  // match maps so they cannot be returned as live resolutions.
   788	  const matchesByRule = new Map<ResolvedEventAttributionRule, Map<string, number>>();
   789	  const matchedEntityIds = new Set<number>();
   790	  for (const [rule, entries] of byRule) {
   791	    const matches = await lookupMatches(sql, {
   792	      orgId: params.orgId,
   793	      identities: entries.map((entry) => entry.link.identities),
   794	    });
   795	    matchesByRule.set(rule, matches);
   796	    for (const entityId of matches.values()) matchedEntityIds.add(entityId);
   797	  }
   798	  if (matchedEntityIds.size > 0) {
   799	    const ids = [...matchedEntityIds].sort((a, b) => a - b);
   800	    const lockedRows = await sql<{ id: number | string }>`
   801	      SELECT id
   802	      FROM entities
   803	      WHERE organization_id = ${params.orgId}
   804	        AND id = ANY(${pgBigintArray(ids)}::bigint[])
   805	        AND deleted_at IS NULL
   806	      ORDER BY id
   807	      FOR UPDATE
   808	    `;
   809	    const lockedIds = new Set(lockedRows.map((row) => Number(row.id)));
   810	    for (const matches of matchesByRule.values()) {
   811	      for (const [key, entityId] of matches) {
   812	        if (!lockedIds.has(entityId)) matches.delete(key);
   813	      }
   814	    }
   815	  }
   816	
   817	  const recordResolved = (index: number, entityId: number): void => {
   818	    const existing = resolvedByItem.get(index);
   819	    if (existing) {
   820	      if (!existing.includes(entityId)) existing.push(entityId);
   821	    } else {
   822	      resolvedByItem.set(index, [entityId]);
   823	    }
   824	  };
   825	
   826	  for (const [rule, entries] of byRule) {
   827	    const matches = matchesByRule.get(rule)!;
   828	
   829	    for (const { index, item, link } of entries) {
   830	      // Tier semantics are defined once in `resolveIdentityTier` and shared
   831	      // with the orphan-recovery re-resolution below. A present primary that
   832	      // matched nothing resolves to null here on purpose: the create path then
   833	      // mints a new entity keyed on it instead of absorbing a stale
   834	      // secondary's owner.
   835	      const tier = resolveIdentityTier(link.identities, matches);
   836	      const ambiguous = tier === 'ambiguous';
   837	      let entityId: number | null = ambiguous ? null : tier;
   838	      let isCreate = false;
   839	
   840	      if (ambiguous) {
   841	        logger.warn(
   842	          {
   843	            orgId: params.orgId,
   844	            connectorKey: params.connectorKey,
   845	            entityType: rule.entityType,
   846	            identifiers: link.identities.map((i) => `${i.namespace}:${i.identifier}`),
   847	          },
   848	          'entityLink merge candidate — multiple entities matched at the same identity tier'
   849	        );
   850	        continue;
   850	        continue;
   851	      }
   852	
   853	      // Identities that ACTUALLY attached to the resolved/created entity. We
   854	      // only ever claim THESE in the in-memory matches map below — an identifier
   855	      // that ON CONFLICT-skipped because another entity already owns it stays
   856	      // with that entity, so the map must not mis-claim it for this one.
   857	      let attached: Array<{ namespace: string; identifier: string }> = [];
   858	      if (entityId !== null) {
   859	        // Matched an existing entity: accrete the non-matchOnly identities; the
   860	        // identifier(s) we matched on already belong to this entity.
   861	        const fresh = await insertIdentities(sql, {
   862	          orgId: params.orgId,
   863	          entityId,
   864	          connectorKey: params.connectorKey,
   865	          connectionId: params.connectionId,
   866	          identities: link.identities.filter((i) => !i.matchOnly),
   867	        });
   868	        attached = [...fresh];
   869	        // Mirror this link's non-matchOnly identifiers into metadata.aliases for
   870	        // metric resolution. Passing the full set (not just `fresh`) repairs a
   871	        // legacy entity whose identities predate aliases-on-create; ensureAliases
   872	        // skips the write once the aliases are complete, so a repeat message from
   873	        // a known sender stays cheap.
   874	        await ensureAliases(sql, {
   875	          orgId: params.orgId,
   876	          entityId,
   877	          identifiers: link.identities.filter((i) => !i.matchOnly).map((i) => i.identifier),
   878	        });
   879	        // The matched identifiers themselves are this entity's even if a
   880	        // re-insert was a no-op (they were how we found it), so claim them too.
   881	        for (const id of link.identities) {
   882	          if (matches.get(`${id.namespace}\u0000${id.identifier}`) === entityId) {
   883	            attached.push({ namespace: id.namespace, identifier: id.identifier });
   884	          }
   885	        }
   886	      } else if (rule.autoCreate && passesCreateWhen(rule.createWhen, item)) {
   887	        if (!creatorUserId) {
   888	          logger.warn(
   889	            { orgId: params.orgId, entityType: rule.entityType },
   890	            'autoCreate skipped: org has no member to attribute as creator'
   891	          );
   892	          continue;
   893	        }
   894	        const created = await createEntityWithIdentities(sql, {
   895	          orgId: params.orgId,
   896	          connectorKey: params.connectorKey,
   897	          connectionId: params.connectionId,
   898	          entityType: rule.entityType,
   899	          title: link.title,
   900	          identities: link.identities,
   901	          traits: link.traits,
   902	          creatorUserId,
   903	        });
   904	        if (created !== null && created.attached.length > 0) {
   905	          entityId = created.entityId;
   906	          attached = created.attached;
   907	          isCreate = true;
   908	        } else if (created !== null) {
   909	          // Concurrent auto-create lost the identity race: every identifier went
   910	          // to the winner via ON CONFLICT, so the row we just inserted is an
   911	          // identity-less orphan. Hard-delete it (no events reference a row born
   912	          // this turn) and re-resolve to the winning entity.
   913	          await hardDeleteEntityRows({ tx: sql, ids: [created.entityId] });
   914	          const winner = await lookupMatches(sql, {
   915	            orgId: params.orgId,
   916	            identities: [link.identities],
   917	          });
   918	          // Re-resolve through the SAME tier rule as the ordinary lookup. A
   919	          // tier-blind union here mis-resolved when the primary's owner was
   920	          // soft-deleted (so the primary matched nothing) while a live entity
   921	          // still held a recycled secondary claim: the union saw exactly one
   922	          // hit and adopted the recycled-claim holder. `member_of` is a read
   923	          // ACL, so that granted one person another person's channel access.
   924	          // Unmatched-primary and ambiguous both leave entityId null → skip,
   925	          // which fails closed (no edge) rather than guessing an owner.
   926	          const winnerTier = resolveIdentityTier(link.identities, winner);
   927	          if (typeof winnerTier === 'number') {
   928	            entityId = winnerTier;
   929	            for (const id of link.identities) {
   930	              if (winner.get(`${id.namespace}\u0000${id.identifier}`) === entityId) {
   931	                attached.push({ namespace: id.namespace, identifier: id.identifier });
   932	              }
   933	            }
   934	          }
   935	        }
   936	      }
   937	
   938	      if (entityId === null) continue;
   939	
   940	      await applyTraits(sql, {
   941	        orgId: params.orgId,
   942	        entityId,
   943	        rule,
   944	        traits: link.traits,
   945	        isCreate,
   946	      });
   947	
   948	      recordResolved(index, entityId);
   949	
   950	      // Cache the mapping for the rest of the batch — only for attached
   951	      // identifiers, so an identifier that stayed on another entity (ON CONFLICT
   952	      // no-op) keeps its existing owner and isn't mis-claimed. EVERY rule's map
   953	      // is updated, not just this one: all maps are resolved up front for the
   954	      // prelock, so a later rule can no longer re-read this create from the DB
   955	      // and would otherwise miss an entity the batch just minted. Sharing the
   956	      // claim is exactly what that re-read returned — `lookupMatches` is
   957	      // type-agnostic and an identity belongs to at most one entity org-wide.
   958	      for (const id of attached) {
   959	        const key = `${id.namespace}\u0000${id.identifier}`;
   960	        for (const ruleMatches of matchesByRule.values()) ruleMatches.set(key, entityId);
   961	      }
   962	
   963	      // Stamp metadata slots for attached identifiers only — read-time JOINs key
   964	      // on events.metadata->>namespace, so a stale slot would mis-attribute.
   965	      //
   966	      // A namespace slot holds ONE value, but an event can carry multiple
   967	      // attribution rules that resolve the SAME namespace to DIFFERENT entities
   968	      // (e.g. an X DM stamps x_user_id for both the `authored_by` sender and the
   969	      // `about` counterparty). Read-time recall can only match one of them via
   970	      // this slot, so first-writer-wins: the earliest-declared rule (the primary
   971	      // author) keeps the slot, and we log the collision so the case that needs a
   972	      // richer, role-aware read model is observable rather than silently dropped.
   973	      // Making role queryable at read time is deliberately a separate change (it
   974	      // touches the shared recall SQL + every call site) — until then this is the
   975	      // honest boundary, not a workaround.
   976	      const md = (item.metadata ??= {});
   977	      for (const id of attached) {
   978	        const existing = md[id.namespace];
   979	        if (existing !== undefined && existing !== id.identifier) {
   980	          logger.warn(
   981	            {
   982	              orgId: params.orgId,
   983	              connectorKey: params.connectorKey,
   984	              namespace: id.namespace,
   985	              kept: existing,
   986	              dropped: id.identifier,
   987	              role: rule.role,
   988	            },
   989	            'attribution metadata slot collision — a later rule resolved the same namespace to a different identifier; keeping the first-stamped value (read-time recall matches only one)'
   990	          );
   991	          continue;
   992	        }
   993	        md[id.namespace] = id.identifier;
   994	      }
   995	    }
   996	  }
   997	
